SINA_SMART["physio-muscle-1"] = {"lecture":"physio-muscle-1","title":"Muscle physiology, part I: skeletal muscle structure","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio-muscle-1:e0","text":"Muscle only pulls: force by shortening, never by pushing.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"physio-muscle-1:e1","text":"Skeletal: multinucleate, peripheral nuclei, striated, voluntary, Ca²⁺ from SR, troponin.","topic":"Three types of muscle","sec":1,"importance":"core","highYield":"untested"},{"id":"physio-muscle-1:e2","text":"Smooth: one central nucleus, no sarcomeres, calmodulin, slowest myosin ATPase.","topic":"Three types of muscle","sec":1,"importance":"core","highYield":"untested"},{"id":"physio-muscle-1:e3","text":"Cardiac: striated, involuntary, intercalated discs with gap junctions, pacemaker.","topic":"Three types of muscle","sec":1,"importance":"core","highYield":"untested"},{"id":"physio-muscle-1:e4","text":"Five properties: contractility, conductivity, excitability, extensibility, elasticity.","topic":"Properties and functions","sec":2,"importance":"core","highYield":"untested"},{"id":"physio-muscle-1:e5","text":"Triad = one T-tubule + two terminal cisternae of the SR.","topic":"Inside a muscle fibre","sec":3,"importance":"core","highYield":"untested"},{"id":"physio-muscle-1:e6","text":"Fibre number fixed at birth; training causes hypertrophy.","topic":"Inside a muscle fibre","sec":3,"importance":"core","highYield":"untested"},{"id":"physio-muscle-1:e7","text":"Myosin hexamer: 2 heavy + 4 light chains; head has the ATP and actin sites.","topic":"Muscle proteins and myosin","sec":4,"importance":"core","highYield":"untested"},{"id":"physio-muscle-1:e10","text":"DHP receptor (T-tubule Ca²⁺ channel) gates the ryanodine receptor (SR); SERCA pumps Ca²⁺ back.","topic":"The sarcomere","sec":5,"importance":"core","highYield":"untested"},{"id":"physio-muscle-1:e8","text":"Z (between), I (isotropic, thin only), A (anisotropic, thick length), H (helles, thick only), M (middle).","topic":"The sarcomere","sec":5,"importance":"core","highYield":"untested"},{"id":"physio-muscle-1:e9","text":"Thin 8 nm, thick 16 nm, about 2 thin per thick.","topic":"The sarcomere","sec":5,"importance":"core","highYield":"untested"},{"id":"physio-muscle-1:e11","text":"Sliding: filaments keep their length; A band constant; I band and H zone shorten.","topic":"Sliding filaments and types of contraction","sec":6,"importance":"core","highYield":"untested"},{"id":"physio-muscle-1:e12","text":"Isotonic shortens; isometric develops tension without shortening.","topic":"Sliding filaments and types of contraction","sec":6,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"1oiavgs":"a","mrf3q1":"a","4flm4p":"a","c2mo6m":"a","1s2qi57":"a","1i1b4mi":"a","1qzdvf8":"a","kmd1r":"a","owjz4s":"a","1guprw0":"a","89ml8c":"a","1c4sp61":"a","17qz41y":"a","31lffg":"a","1dovgzl":"a","1b033s4":"a","1lv18z":"x","mjrzwk":"x"},"mapCounts":{"verified":0,"auto":16,"ambiguous":0,"missing":2},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio-muscle-1:e0":{"s":0,"u":["Muscle only pulls: force by shortening, never by pushing.","It produces force by shortening, never by pushing or lengthening.","One rule to keep: muscle can only pull ."],"dp":[]},"physio-muscle-1:e1":{"s":1,"u":["Skeletal: multinucleate, peripheral nuclei, striated, voluntary, Ca²⁺ from SR, troponin.","Nuclei: Skeletal = Many, peripheral; Smooth = One, central; Cardiac = One, central.","Ca²⁺-binding protein: Skeletal = Troponin; Smooth = Calmodulin; Cardiac = Troponin."],"dp":[{"h":"Calcium tells you the muscle type","t":"Skeletal muscle keeps all its trigger Ca²⁺ in the SR and reads it with troponin, which makes it fast and tightly controlled by nerves. Smooth muscle also uses extracellular Ca²⁺ and reads it with calmodulin through a slower enzyme cascade, which suits slow, sustained tone in vessel and gut walls. Cardiac muscle sits in between. Most comparison questions in this lecture can be answered from this one difference. Source: the lecture's comparison table of skeletal, smooth and cardiac muscle."}]},"physio-muscle-1:e2":{"s":1,"u":["Smooth: one central nucleus, no sarcomeres, calmodulin, slowest myosin ATPase.","Myosin ATPase: Skeletal = Fastest; Smooth = Slowest; Cardiac = Intermediate.","Nuclei: Skeletal = Many, peripheral; Smooth = One, central; Cardiac = One, central."],"dp":[]},"physio-muscle-1:e3":{"s":1,"u":["Cardiac: striated, involuntary, intercalated discs with gap junctions, pacemaker.","Gap junctions: Skeletal = No; Smooth = Yes (single-unit); Cardiac = Yes (intercalated discs).","Control: Skeletal = Voluntary (and reflexes); somatic nerves; Smooth = Involuntary; autonomic and hormones; Cardiac = Involuntary; pacemaker, autonomic, adrenaline."],"dp":[]},"physio-muscle-1:e4":{"s":2,"u":["Five properties: contractility, conductivity, excitability, extensibility, elasticity.","Extensibility : can be stretched.","Elasticity : recoils to resting length."],"dp":[]},"physio-muscle-1:e5":{"s":3,"u":["Triad = one T-tubule + two terminal cisternae of the SR.","Triad: One T-tubule + two terminal cisternae.","Sarcoplasmic reticulum (SR): Endoplasmic reticulum around each myofibril; its terminal cisternae concentrate Ca²⁺ with pumps and release it to start contraction."],"dp":[]},"physio-muscle-1:e6":{"s":3,"u":["Fibre number fixed at birth; training causes hypertrophy.","The number of fibres is fixed at birth : training enlarges fibres ( hypertrophy ), it does not add new ones."],"dp":[]},"physio-muscle-1:e7":{"s":4,"u":["Myosin hexamer: 2 heavy + 4 light chains; head has the ATP and actin sites.","Myosin is a hexamer: 2 heavy chains + 4 light chains .","The head (S1 fragment) holds all the motor function: an N-terminal catalytic domain with the nucleotide (ATP) binding site and the actin-binding site."],"dp":[]},"physio-muscle-1:e10":{"s":5,"u":["DHP receptor (T-tubule Ca²⁺ channel) gates the ryanodine receptor (SR); SERCA pumps Ca²⁺ back.","SR: ryanodine receptors (Ca²⁺ channels gated by the DHP receptors) and the SR Ca²⁺ ATPase (SERCA, removes Ca²⁺ from the sarcoplasm).","Membrane proteins : sarcolemma: voltage-gated Na⁺ channels (propagate APs), the DHP receptor (a voltage-gated Ca²⁺ channel in the T-tubule) and the Na⁺/K⁺ ATPase."],"dp":[]},"physio-muscle-1:e8":{"s":5,"u":["Z (between), I (isotropic, thin only), A (anisotropic, thick length), H (helles, thick only), M (middle).","A band: Name means = Anisotropic (dark); Contains = The full length of the thick filaments (with overlapping thin ones).","Filaments are 1 to 2 µm long; thin filaments about 8 nm wide, thick about 16 nm ; about 2 thin filaments per thick filament ."],"dp":[]},"physio-muscle-1:e9":{"s":5,"u":["Thin 8 nm, thick 16 nm, about 2 thin per thick.","Filaments are 1 to 2 µm long; thin filaments about 8 nm wide, thick about 16 nm ; about 2 thin filaments per thick filament .","A band: Name means = Anisotropic (dark); Contains = The full length of the thick filaments (with overlapping thin ones)."],"dp":[]},"physio-muscle-1:e11":{"s":6,"u":["Sliding: filaments keep their length; A band constant; I band and H zone shorten.","The A band stays the same ; the I band and H zone shorten (and can disappear at full contraction)."],"dp":[{"h":"Why the A band never changes","t":"The A band is defined by the thick filaments, and myosin filaments do not change length. When the muscle contracts, the thin filaments slide in from both sides, so the light zones that contain only one type of filament (the I band with actin only, the H zone with myosin only) get smaller, while the dark A band stays exactly as wide. Ask yourself which filament defines each band and the answer to any 'what shortens' question follows. Source: the lecture's sliding filament slides."}]},"physio-muscle-1:e12":{"s":6,"u":["Isotonic shortens; isometric develops tension without shortening.","Isotonic contraction: the muscle shortens (load moves).","Isometric contraction: myosin heads rotate and generate tension, but the thin filaments cannot slide because the opposing load is too great, so the muscle does not shorten ."],"dp":[]}},"meta":{"1oiavgs":{"a":"recall","vg":"physio-muscle-1:e1/recall/1"},"mrf3q1":{"a":"recall","vg":"physio-muscle-1:e1/recall/2"},"4flm4p":{"a":"recall","vg":"physio-muscle-1:e2/recall/1"},"c2mo6m":{"a":"recall","vg":"physio-muscle-1:e5/recall/1"},"1s2qi57":{"a":"recall","vg":"physio-muscle-1:e5/recall/2"},"1i1b4mi":{"a":"recall","vg":"physio-muscle-1:e6/recall/1"},"1qzdvf8":{"a":"recall","vg":"physio-muscle-1:e7/recall/1"},"kmd1r":{"a":"recall","vg":"physio-muscle-1:e7/recall/2"},"owjz4s":{"a":"recall","vg":"physio-muscle-1:e9/recall/1"},"1guprw0":{"a":"recall","vg":"physio-muscle-1:e11/recall/1"},"89ml8c":{"a":"recall","vg":"physio-muscle-1:e8/recall/1"},"1c4sp61":{"a":"recall","vg":"physio-muscle-1:e10/recall/1"},"17qz41y":{"a":"recall","vg":"physio-muscle-1:e10/recall/2"},"31lffg":{"a":"recall","vg":"physio-muscle-1:e12/recall/1"},"1dovgzl":{"a":"recall","vg":"physio-muscle-1:e4/recall/1"},"1b033s4":{"a":"recall","vg":"physio-muscle-1:e2/recall/2"}},"explRev":"1ec31a5b98e8"};
